python3 -c "
import re
raw=open('C:/Users/vamsh/AppData/Local/Temp/opencode/run_a176359f.log','rb').read()
log=raw.decode('utf-16',errors='replace').splitlines()
from collections import Counter
kinds=Counter()
for l in log:
    c=re.sub(r'[^ -~]','?',re.sub(r'\s+',' ',l))
    m=re.match(r'\[(erp|submit|mail|customer-portal|tender-portal|courier) \d+.*\| (\[.*)',c)
    if m:
        try:
            import json
            acts=json.loads(m.group(2).split('|')[0].strip().rstrip('|').strip())
            if isinstance(acts,dict): acts=[acts]
            for a in acts:
                if isinstance(a,dict):
                    k=a.get('do','?')
                    if k=='steps':
                        k='steps(%d)'%len(a.get('steps',[]))
                    kinds[m.group(1)+':'+k]+=1
        except Exception: pass
for k in sorted(kinds): print(kinds[k],k)
"

